import { MakeLogicType, actions, connect, kea, key, listeners, path, props, reducers, selectors } from 'kea'
import posthog from 'posthog-js'

import { userPreferencesLogic } from 'lib/logic/userPreferencesLogic'

import { CustomerProfileConfigType, CustomerProfileScope } from '~/types'

import { customerProfileConfigLogic } from './customerProfileConfigLogic'

export interface PinnedProfilePropertiesLogicProps {
    scope: CustomerProfileScope
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface pinnedProfilePropertiesLogicValues {
    customerProfileConfig: CustomerProfileConfigType | undefined // customerProfileConfigLogic
    pinnedGroupProperties: string[] | null // userPreferencesLogic
    pinnedPersonProperties: string[] | null // userPreferencesLogic
    defaultPinnedGroupProperties: string[] // userPreferencesLogic
    defaultPinnedPersonProperties: string[] // userPreferencesLogic
    defaultPinnedProperties: string[]
    hasOwnPins: boolean
    ownPinnedProperties: string[] | null
    pinnedProperties: string[]
    savingTeamDefault: boolean
    teamPinnedProperties: string[] | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface pinnedProfilePropertiesLogicActions {
    createConfig: (config: Partial<CustomerProfileConfigType>) => {
        config: Partial<CustomerProfileConfigType>
    } // customerProfileConfigLogic
    setPinnedGroupProperties: (props: string[] | null) => {
        props: string[] | null
    } // userPreferencesLogic
    setPinnedPersonProperties: (props: string[] | null) => {
        props: string[] | null
    } // userPreferencesLogic
    updateConfig: (
        id: CustomerProfileConfigType['id'],
        config: Partial<CustomerProfileConfigType>
    ) => {
        config: Partial<CustomerProfileConfigType>
        id: string
    } // customerProfileConfigLogic
    pinProperty: (property: string) => {
        property: string
    }
    setAsTeamDefault: () => {
        value: true
    }
    unpinProperty: (property: string) => {
        property: string
    }
    useTeamDefault: () => {
        value: true
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface pinnedProfilePropertiesLogicMeta {
    key: CustomerProfileScope
    __keaTypeGenInternalSelectorTypes: {
        ownPinnedProperties: (a: string[] | null, b: string[] | null, c: any) => string[] | null
        hasOwnPins: (a: string[] | null) => boolean
        teamPinnedProperties: (a: CustomerProfileConfigType | undefined) => string[] | null
        defaultPinnedProperties: (a: string[], b: string[], c: any) => string[]
        pinnedProperties: (a: string[] | null, b: string[] | null, c: string[]) => string[]
    }
}

export type pinnedProfilePropertiesLogicType = MakeLogicType<
    pinnedProfilePropertiesLogicValues,
    pinnedProfilePropertiesLogicActions,
    PinnedProfilePropertiesLogicProps,
    pinnedProfilePropertiesLogicMeta
>

/**
 * Resolves which properties a profile pins, from the team-wide default a teammate saved and the
 * pins this person made in their own browser. The team default is what makes a profile view
 * shared: a teammate who has never pinned anything sees the pins the team agreed on.
 */
export const pinnedProfilePropertiesLogic = kea<pinnedProfilePropertiesLogicType>([
    props({} as PinnedProfilePropertiesLogicProps),
    key((props) => props.scope),
    path((key) => ['products', 'customer_analytics', 'pinnedProfilePropertiesLogic', key]),

    connect((props: PinnedProfilePropertiesLogicProps) => ({
        values: [
            userPreferencesLogic,
            [
                'pinnedPersonProperties',
                'pinnedGroupProperties',
                'defaultPinnedPersonProperties',
                'defaultPinnedGroupProperties',
            ],
            customerProfileConfigLogic({ scope: props.scope }),
            ['customerProfileConfig'],
        ],
        actions: [
            userPreferencesLogic,
            ['setPinnedPersonProperties', 'setPinnedGroupProperties'],
            customerProfileConfigLogic({ scope: props.scope }),
            ['createConfig', 'updateConfig'],
        ],
    })),

    actions({
        pinProperty: (property: string) => ({ property }),
        unpinProperty: (property: string) => ({ property }),
        setAsTeamDefault: true,
        useTeamDefault: true,
    }),

    reducers(({ props }) => {
        const { actionTypes } = customerProfileConfigLogic({ scope: props.scope })
        const settled = [
            actionTypes.createConfigSuccess,
            actionTypes.createConfigFailure,
            actionTypes.updateConfigSuccess,
            actionTypes.updateConfigFailure,
        ]
        return {
            // `configsLoading` also covers the list request every panel makes on mount, so track our
            // own write instead. It guards the menu item against a second click during a save.
            savingTeamDefault: [
                false,
                {
                    setAsTeamDefault: () => true,
                    ...Object.fromEntries(settled.map((actionType) => [actionType, () => false])),
                },
            ],
        }
    }),

    selectors({
        ownPinnedProperties: [
            (s) => [s.pinnedPersonProperties, s.pinnedGroupProperties, (_, props) => props.scope],
            (pinnedPersonProperties, pinnedGroupProperties, scope): string[] | null =>
                scope === CustomerProfileScope.PERSON ? pinnedPersonProperties : pinnedGroupProperties,
        ],
        hasOwnPins: [(s) => [s.ownPinnedProperties], (ownPinnedProperties): boolean => ownPinnedProperties !== null],
        teamPinnedProperties: [
            (s) => [s.customerProfileConfig],
            (customerProfileConfig): string[] | null => {
                const pins = customerProfileConfig?.pinned_properties
                // An older config row, or one saved for its layout only, carries an empty list. That
                // means the team never agreed on pins, not that the team pinned nothing.
                return Array.isArray(pins) && pins.length ? pins : null
            },
        ],
        defaultPinnedProperties: [
            (s) => [s.defaultPinnedPersonProperties, s.defaultPinnedGroupProperties, (_, props) => props.scope],
            (defaultPinnedPersonProperties, defaultPinnedGroupProperties, scope): string[] =>
                scope === CustomerProfileScope.PERSON ? defaultPinnedPersonProperties : defaultPinnedGroupProperties,
        ],
        pinnedProperties: [
            (s) => [s.ownPinnedProperties, s.teamPinnedProperties, s.defaultPinnedProperties],
            (ownPinnedProperties, teamPinnedProperties, defaultPinnedProperties): string[] =>
                ownPinnedProperties ?? teamPinnedProperties ?? defaultPinnedProperties,
        ],
    }),

    listeners(({ actions, values, props }) => {
        const setOwnPins = (pins: string[] | null): void => {
            if (props.scope === CustomerProfileScope.PERSON) {
                actions.setPinnedPersonProperties(pins)
            } else {
                actions.setPinnedGroupProperties(pins)
            }
        }

        return {
            pinProperty: ({ property }) => {
                const { pinnedProperties, hasOwnPins, teamPinnedProperties } = values
                if (!pinnedProperties.includes(property)) {
                    setOwnPins([...pinnedProperties, property])
                }
                posthog.capture('customer profile property pinned', {
                    scope: props.scope,
                    followed_team_default: !hasOwnPins && teamPinnedProperties !== null,
                })
            },
            unpinProperty: ({ property }) => {
                setOwnPins(values.pinnedProperties.filter((pin) => pin !== property))
                posthog.capture('customer profile property unpinned', { scope: props.scope })
            },
            setAsTeamDefault: () => {
                const pinned_properties = values.pinnedProperties
                const config = values.customerProfileConfig
                if (config) {
                    actions.updateConfig(config.id, { pinned_properties })
                } else {
                    actions.createConfig({ scope: props.scope, pinned_properties })
                }
                posthog.capture('customer profile pinned properties shared with team', {
                    scope: props.scope,
                    property_count: pinned_properties.length,
                    replaced_existing_default: values.teamPinnedProperties !== null,
                })
            },
            useTeamDefault: () => {
                setOwnPins(null)
            },
        }
    }),
])
